def get_max_sum(n):
    memo = {0: 0, 1: 1}

    def helper(x):
        if x <= 0:
            return 0
        if x not in memo:
            memo[x] = max(x, helper(x // 2) + helper(x // 3) + helper(x // 4) + helper(x // 5))
        return memo[x]

    return helper(n)

