def parse_record(line):
    """Parse a record line into a dict.
    - Fields are separated by ";". Empty fields are ignored.
    - A field is either key=value or a bare key, which maps to True.
    - Keys and unquoted values have surrounding whitespace removed.
    - A value may be wrapped in double quotes: inside the quotes ";" is literal, \\" is an escaped
      quote, and the text is kept exactly (no trimming). The quotes themselves are removed.
    - If a key repeats, the later value wins.

    parse_record('name=Ana; city = Lyon') == {"name": "Ana", "city": "Lyon"}
    parse_record('note="a;b"; urgent') == {"note": "a;b", "urgent": True}
    """
    fields = []
    current = []
    in_quotes = False
    escape = False

    for ch in line:
        if escape:
            current.append(ch)
            escape = False
        elif ch == "\\" and in_quotes:
            current.append(ch)
            escape = True
        elif ch == '"':
            in_quotes = not in_quotes
            current.append(ch)
        elif ch == ";" and not in_quotes:
            fields.append("".join(current))
            current = []
        else:
            current.append(ch)
    fields.append("".join(current))

    result = {}
    for field in fields:
        if not field.strip():
            continue
        if "=" not in field:
            result[field.strip()] = True
        else:
            key, raw_val = field.split("=", 1)
            key = key.strip()
            raw_val = raw_val.strip()
            if len(raw_val) >= 2 and raw_val.startswith('"') and raw_val.endswith('"'):
                inner = raw_val[1:-1]
                val_chars = []
                esc = False
                for c in inner:
                    if esc:
                        if c in ('"', "\\"):
                            val_chars.append(c)
                        else:
                            val_chars.append("\\")
                            val_chars.append(c)
                        esc = False
                    elif c == "\\":
                        esc = True
                    else:
                        val_chars.append(c)
                if esc:
                    val_chars.append("\\")
                val = "".join(val_chars)
            else:
                val = raw_val
            result[key] = val

    return result

