def comb_sort(nums):
    shrink_fact = 1.3
    gaps = len(nums)
    swapped = True

    while gaps > 1 or swapped:
        gaps = int(float(gaps) / shrink_fact)
        if gaps < 1:
            gaps = 1

        swapped = False
        i = 0

        while i + gaps < len(nums):
            if nums[i] > nums[i + gaps]:
                nums[i], nums[i + gaps] = nums[i + gaps], nums[i]
                swapped = True
            i += 1

    return nums

